 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, DoubleSide, ClampToEdgeWrapping, SRGBColorSpace } = ctx.THREE;

  // --- resolve design tokens -------------------------------------------------
  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#0b0b10';

  // --- resolve text ----------------------------------------------------------
  const items = config.textContent ?? spec.textContent ?? [];
  const headline = items.find(i => i.role === 'headline') ?? items[0] ?? {};
  const labelText = headline.text ?? 'Features 3';
  const labelSize = headline.typography?.fontSize ?? 39;

  // --- resolve atlas region --------------------------------------------------
  const rawRegion = spec.atlasRegion ?? config.atlasRegion ?? {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
    atlasWidth: 512,
    atlasHeight: 320,
  };

  const region = {
    x: rawRegion.x ?? 0,
    y: rawRegion.y ?? 0,
    width: rawRegion.width ?? rawRegion.w ?? 512,
    height: rawRegion.height ?? rawRegion.h ?? 320,
    atlasWidth: rawRegion.atlasWidth ?? rawRegion.atlasW ?? 512,
    atlasHeight: rawRegion.atlasHeight ?? rawRegion.atlasH ?? 320,
  };

  // --- sprite sizing (preserve atlas aspect) ---------------------------------
  const cardWidth = 1.2;
  const cardHeight = cardWidth / (region.width / region.height);

  // --- build scene object ----------------------------------------------------
  const group = new Group();

  const geometry = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: false,
  });
  material.color.set(surface);

  const plane = new Mesh(geometry, material);
  plane.onBeforeRender = (renderer, scene, camera) => {
    if (!camera) return;
    group.lookAt(camera.position);
  };
  group.add(plane);

  // --- label text ------------------------------------------------------------
  const label = ctx.fontAtlas.createText(labelText, {
    fontSize: labelSize,
    color: paper,
    align: 'left',
  });
  label.position.set(-cardWidth * 0.5 + 0.12, 0, 0.025);
  group.add(label);

  // --- cinematic primitives --------------------------------------------------
  const timelines = [];
  const primitiveCleanups = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](group, p.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  // --- handlers (empty for static label) -------------------------------------
  group.userData.handlers = {};

  // --- asset load ------------------------------------------------------------
  let cardTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardTexture = tex;
      cardTexture.colorSpace = SRGBColorSpace;
      cardTexture.wrapS = ClampToEdgeWrapping;
      cardTexture.wrapT = ClampToEdgeWrapping;
      cardTexture.needsUpdate = true;

      const atlasW = region.atlasWidth || cardTexture.image?.width || region.width;
      const atlasH = region.atlasHeight || cardTexture.image?.height || region.height;

      const repeatX = region.width / atlasW;
      const repeatY = region.height / atlasH;
      const offsetX = region.x / atlasW;
      const offsetY = region.y / atlasH;

      material.colorNode = texture(
        cardTexture,
        uv()
          .mul(vec2(repeatX, repeatY))
          .add(vec2(offsetX, offsetY))
      ).rgb;

      material.needsUpdate = true;
    }).catch(() => {
      // keep fallback surface color on failure
    });
  }

  // --- cleanup ---------------------------------------------------------------
  group.userData.cleanup = () => {
    plane.onBeforeRender = null;

    timelines.forEach(t => t?.kill?.());
    primitiveCleanups.forEach(fn => fn?.());

    material.colorNode = null;
    material.dispose();
    geometry.dispose();

    if (cardTexture?.isTexture) {
      cardTexture.dispose();
    }

    if (group.parent) group.parent.remove(group);
  };

  return group;
}
